<template>
  <main class="image-zone">
    <header class="zone-header">
      <button class="button button-ghost" type="button" @click="$router.push('/personal/entertainment')"><AppIcon name="arrow-left" :size="17"/>返回媒体库</button>
      <div><p class="eyebrow">Media library</p><h1>图片</h1><p class="muted">查看、整理、下载并安全编辑仅属于你的图片。</p></div>
    </header>
    <section class="toolbar" aria-label="图片操作">
      <p v-if="isFiltering" class="muted">已选择 {{ selectedImages.length }} 张图片</p><span v-else></span>
      <div class="actions">
        <template v-if="!isFiltering"><button class="button" type="button" @click="startFilter">选择多项</button><button class="button button-primary" type="button" @click="showUpload=true"><AppIcon name="upload" :size="17"/>上传图片</button></template>
        <template v-else><button class="button" type="button" :disabled="!selectedImages.length" @click="showCategorize=true"><AppIcon name="tag" :size="17"/>归类</button><button class="button button-danger" type="button" :disabled="!selectedImages.length" @click="showDelete=true"><AppIcon name="trash" :size="17"/>删除</button><button class="button button-ghost" type="button" @click="cancelFilter">取消</button></template>
      </div>
    </section>
    <div v-if="loading" class="empty"><AppIcon name="image"/><p>正在载入图片…</p></div>
    <div v-else-if="loadError" class="empty"><AppIcon name="info"/><p>{{loadError}}</p><button class="button" type="button" @click="loadImages">重试</button></div>
    <div v-else-if="!images.length" class="empty"><AppIcon name="image" :size="28"/><p>还没有图片。</p><button class="button button-primary" type="button" @click="showUpload=true">上传图片</button></div>
    <section v-else class="images-grid" aria-label="图片列表">
      <button v-for="image in images" :key="image.id" class="image-card" type="button" :class="{selected:selectedImages.includes(image.id)}" :aria-pressed="isFiltering?selectedImages.includes(image.id):undefined" :aria-label="isFiltering ? `选择图片 ${image.title}` : `查看图片 ${image.title}`" @click="handleImage(image)">
        <span v-if="isFiltering" class="selection"><AppIcon v-if="selectedImages.includes(image.id)" name="check" :size="16"/></span>
        <img :src="imageUrl(image)" :alt="image.title"/>
        <span class="format">{{image.file_type}}</span>
        <span class="image-info"><strong>{{image.title}}</strong><small>{{image.width||'?'}} × {{image.height||'?'}} · {{image.style||'普通'}}</small></span>
      </button>
    </section>

    <div v-if="viewingImage" class="overlay" role="dialog" aria-modal="true" aria-label="图片预览" @click.self="closeViewer">
      <section class="viewer"><header><button class="icon-button" type="button" aria-label="关闭预览" @click="closeViewer"><AppIcon name="close"/></button><h2>{{viewingImage.title}}</h2><button class="button" type="button" @click="downloadImage"><AppIcon name="download" :size="17"/>下载</button></header>
        <div class="viewer-body"><div class="viewer-image"><button class="icon-button" type="button" aria-label="上一张" :disabled="!hasPrev" @click="prevImage"><AppIcon name="arrow-left"/></button><img :src="imageUrl(viewingImage)" :alt="viewingImage.title"/><button class="icon-button" type="button" aria-label="下一张" :disabled="!hasNext" @click="nextImage"><AppIcon name="arrow-right"/></button></div>
          <aside class="details"><div class="details-head"><h3>图片信息</h3><button v-if="!isEditing" class="button button-ghost" type="button" @click="isEditing=true"><AppIcon name="pen" :size="16"/>编辑</button></div>
            <div class="field"><label for="image-title">标题</label><input id="image-title" v-model="editForm.title" :disabled="!isEditing"/></div><div class="field"><label for="image-style">分类</label><select id="image-style" v-model="editForm.style" :disabled="!isEditing"><option v-for="style in styles" :key="style">{{style}}</option></select></div><div class="field"><label for="image-description">描述</label><textarea id="image-description" v-model="editForm.description" :disabled="!isEditing" rows="4"/></div><p class="muted">{{viewingImage.file_type}} · {{viewingImage.width||'?'}} × {{viewingImage.height||'?'}}</p>
            <div v-if="isEditing" class="actions"><button class="button" type="button" @click="cancelMetadata">取消</button><button class="button button-primary" type="button" :disabled="metadataSaving" @click="saveMetadata">{{metadataSaving?'保存中…':'保存'}}</button></div>
            <button class="button button-primary editor-launch" type="button" @click="openEditor"><AppIcon name="pen" :size="17"/>编辑图片</button>
          </aside></div>
      </section>
    </div>

    <div v-if="showEditor" class="overlay" role="dialog" aria-modal="true" aria-label="图片编辑器" @click.self="requestCloseEditor">
      <section class="editor"><header><div><p class="eyebrow">Image editor</p><h2>{{viewingImage?.title}}</h2></div><div class="actions"><span class="muted" aria-live="polite">{{editorStatus}}</span><button class="button button-ghost" type="button" :disabled="savingEditor" @click="requestCloseEditor">关闭</button><button class="button button-primary" type="button" :disabled="!canExport||savingEditor" @click="showSaveOptions=true">保存</button></div></header>
        <p v-if="editorError" class="error" role="alert">{{editorError}}</p>
        <div class="editor-body"><section class="canvas-panel"><p v-if="editorLoading" class="muted">正在载入图片…</p><div v-else class="canvas-stage"><canvas ref="editorCanvas" @pointerdown="beginCrop" @pointermove="moveCrop" @pointerup="endCrop" @pointercancel="endCrop"></canvas><div v-if="isCropping&&cropRect" class="crop-box" :style="cropStyle" @pointerdown.stop="beginCropMove" @pointermove.stop="moveCrop" @pointerup.stop="endCrop" @pointercancel.stop="endCrop"><span v-for="handle in cropHandles" :key="handle" class="crop-handle" :class="`h-${handle}`" :data-handle="handle" @pointerdown.stop="beginResize"/></div></div><p v-if="isCropping" class="muted">拖动建立选区；拖动边缘或边角调整。最小尺寸为 32 像素。</p></section>
          <aside class="tools"><section><h3>滤镜</h3><div class="tool-row"><button v-for="filter in filters" :key="filter.value" class="button button-ghost" type="button" :aria-pressed="filterMode===filter.value" @click="setFilter(filter.value)">{{filter.label}}</button></div></section><section><h3>调整</h3><label v-for="control in controls" :key="control.key" class="range">{{control.label}} <output>{{adjustments[control.key]}}%</output><input v-model.number="adjustments[control.key]" type="range" min="0" max="200" @input="renderEditor"/></label></section><section><h3>方向</h3><div class="tool-row"><button class="icon-button" type="button" aria-label="逆时针旋转 90 度" @click="rotate(-90)"><AppIcon name="rotate-ccw"/></button><button class="icon-button" type="button" aria-label="顺时针旋转 90 度" @click="rotate(90)"><AppIcon name="rotate-cw"/></button><button class="icon-button" type="button" aria-label="水平翻转" @click="flip('x')"><AppIcon name="flip-horizontal"/></button><button class="icon-button" type="button" aria-label="垂直翻转" @click="flip('y')"><AppIcon name="flip-vertical"/></button></div></section><section><h3>裁剪</h3><div class="tool-row"><button class="button" type="button" @click="startCrop"><AppIcon name="crop" :size="16"/>{{isCropping?'重新选择':'开始裁剪'}}</button><button v-if="isCropping" class="button button-primary" type="button" :disabled="!cropRect" @click="applyCrop">应用</button><button v-if="isCropping" class="button button-ghost" type="button" @click="cancelCrop">取消</button></div></section><section><h3>输出格式</h3><select v-model="outputFormat" aria-label="输出格式"><option value="image/jpeg">JPEG</option><option value="image/png">PNG</option><option value="image/webp">WebP</option></select><button class="button button-ghost" type="button" @click="resetEditor">重置全部编辑</button></section></aside>
        </div></section>
    </div>

    <BaseModal v-if="showSaveOptions" title="保存编辑结果" @close="showSaveOptions=false"><p>生成新图片会保留原图；替换原图需要再次确认。</p><template #actions><button class="button" type="button" @click="saveAsNew">生成新图片</button><button class="button button-danger" type="button" @click="showReplaceConfirm=true">替换原图</button></template></BaseModal>
    <BaseModal v-if="showReplaceConfirm" title="确认替换原图" @close="showReplaceConfirm=false"><p>此操作会更新原图片文件，无法从媒体库恢复旧文件。</p><template #actions><button class="button button-danger" type="button" :disabled="savingEditor" @click="replaceImage">{{savingEditor?'替换中…':'确认替换'}}</button></template></BaseModal>
    <BaseModal v-if="showNewImage" title="生成新图片" @close="showNewImage=false"><div class="field"><label for="new-image-title">新图片名称</label><input id="new-image-title" v-model="newImageTitle"/></div><template #actions><button class="button button-primary" type="button" :disabled="savingEditor" @click="createDerivative">{{savingEditor?'生成中…':'生成'}}</button></template></BaseModal>
    <BaseModal v-if="showDiscard" title="放弃未保存编辑？" @close="showDiscard=false"><p>关闭后，本次 Canvas 编辑不会保存。</p><template #actions><button class="button button-danger" type="button" @click="closeEditor">放弃编辑</button></template></BaseModal>
    <BaseModal v-if="showCategorize" title="批量归类" @close="showCategorize=false"><div class="field"><label for="bulk-style">分类</label><input id="bulk-style" v-model="categorizeStyle" list="image-styles"/></div><template #actions><button class="button button-primary" type="button" @click="categorize">保存</button></template></BaseModal>
    <BaseModal v-if="showDelete" title="确认删除图片" @close="showDelete=false"><p>将永久删除 {{selectedImages.length}} 张图片及文件。</p><template #actions><button class="button button-danger" type="button" @click="deleteImages">确认删除</button></template></BaseModal>
    <BaseModal v-if="showUpload" title="上传图片" @close="showUpload=false"><div class="field"><label for="upload-title">名称</label><input id="upload-title" v-model="uploadForm.title" placeholder="默认为文件名"/></div><div class="field"><label for="upload-style">分类</label><select id="upload-style" v-model="uploadForm.style"><option v-for="style in styles" :key="style">{{style}}</option></select></div><div class="field"><label for="upload-file">文件</label><input id="upload-file" type="file" accept="image/*" @change="selectFile"/></div><template #actions><button class="button button-primary" type="button" :disabled="!uploadForm.file||uploading" @click="uploadImage">{{uploading?'上传中…':'上传'}}</button></template></BaseModal>
    <datalist id="image-styles"><option v-for="style in styles" :key="style" :value="style"/></datalist><div v-if="toast.show" class="toast" :class="toast.type" role="status">{{toast.message}}</div>
  </main>
</template>

<script>
import axios from '@/services/http'
import AppIcon from '@/components/AppIcon.vue'
const BaseModal={props:{title:String},emits:['close'],components:{AppIcon},template:`<div class="modal-overlay" @click.self="$emit('close')"><section class="modal" role="dialog" aria-modal="true" :aria-label="title"><header><h2>{{title}}</h2><button class="icon-button" type="button" aria-label="关闭" @click="$emit('close')"><AppIcon name="close"/></button></header><div class="modal-body"><slot/></div><footer><button class="button button-ghost" type="button" @click="$emit('close')">取消</button><slot name="actions"/></footer></section></div>`}
export default {name:'ImageZone',components:{AppIcon,BaseModal},data:()=>({images:[],loading:true,loadError:'',isFiltering:false,selectedImages:[],viewingImage:null,currentImageIndex:0,isEditing:false,metadataSaving:false,editForm:{title:'',style:'普通',description:''},styles:['普通','风景','人物','动漫','美食','其他'],showUpload:false,uploading:false,uploadForm:{title:'',style:'普通',file:null},showCategorize:false,categorizeStyle:'',showDelete:false,showEditor:false,showSaveOptions:false,showReplaceConfirm:false,showNewImage:false,showDiscard:false,newImageTitle:'',originalCanvas:null,sourceCanvas:null,editorCanvas:null,editorLoading:false,editorError:'',editorStatus:'',savingEditor:false,editorDirty:false,adjustments:{brightness:100,contrast:100,saturation:100},filterMode:'none',rotation:0,flipH:1,flipV:1,isCropping:false,cropRect:null,cropAction:null,cropOrigin:null,outputFormat:'image/jpeg',toast:{show:false,message:'',type:'success'},toastTimer:null}),computed:{hasPrev(){return this.currentImageIndex>0},hasNext(){return this.currentImageIndex<this.images.length-1},canExport(){return !!this.sourceCanvas&&!this.editorLoading&&!this.editorError},cropHandles:()=>['nw','n','ne','e','se','s','sw','w'],cropStyle(){const r=this.cropRect,c=this.editorCanvas;if(!r||!c)return{};return{left:`${r.x/c.width*100}%`,top:`${r.y/c.height*100}%`,width:`${r.width/c.width*100}%`,height:`${r.height/c.height*100}%`}},filters:()=>[{label:'原始',value:'none'},{label:'黑白',value:'grayscale(1)'},{label:'复古',value:'sepia(1)'},{label:'明亮',value:'brightness(1.2)'},{label:'对比',value:'contrast(1.2)'}],controls:()=>[{key:'brightness',label:'亮度'},{key:'contrast',label:'对比度'},{key:'saturation',label:'饱和度'}]},created(){if(!localStorage.getItem('userId'))return this.$router.push('/login');this.loadImages();document.addEventListener('keydown',this.onEscape)},beforeUnmount(){document.removeEventListener('keydown',this.onEscape);clearTimeout(this.toastTimer)},methods:{
onEscape(e){if(e.key==='Escape'){if(this.showEditor)this.requestCloseEditor();else if(this.viewingImage)this.closeViewer()}},imageUrl(image){return `/api/entertainment/image-file/${image.id}${image.cacheKey?`?v=${image.cacheKey}`:''}`},notify(message,type='success'){this.toast={show:true,message,type};clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>this.toast.show=false,3200)},async loadImages(){this.loading=true;this.loadError='';try{this.images=(await axios.get(`/api/entertainment/images/${localStorage.getItem('userId')}`)).data.images||[]}catch(e){this.loadError=e.response?.data?.error||'图片加载失败'}finally{this.loading=false}},startFilter(){this.isFiltering=true;this.selectedImages=[]},cancelFilter(){this.isFiltering=false;this.selectedImages=[]},handleImage(image){if(this.isFiltering){const i=this.selectedImages.indexOf(image.id);i<0?this.selectedImages.push(image.id):this.selectedImages.splice(i,1)}else this.viewImage(image)},viewImage(image){this.viewingImage=image;this.currentImageIndex=this.images.findIndex(x=>x.id===image.id);this.editForm={title:image.title,style:image.style||'普通',description:image.description||image.title};this.isEditing=false},closeViewer(){this.viewingImage=null},prevImage(){if(this.hasPrev)this.viewImage(this.images[this.currentImageIndex-1])},nextImage(){if(this.hasNext)this.viewImage(this.images[this.currentImageIndex+1])},cancelMetadata(){this.editForm={title:this.viewingImage.title,style:this.viewingImage.style||'普通',description:this.viewingImage.description||this.viewingImage.title};this.isEditing=false},async saveMetadata(){this.metadataSaving=true;try{await axios.put(`/api/entertainment/images/${this.viewingImage.id}`,this.editForm);Object.assign(this.viewingImage,this.editForm);this.isEditing=false;this.notify('图片信息已保存');this.loadImages()}catch(e){this.notify(e.response?.data?.error||'保存失败','error')}finally{this.metadataSaving=false}},downloadImage(){const link=document.createElement('a');link.href=this.imageUrl(this.viewingImage);link.download=`${this.viewingImage.title}${this.viewingImage.file_type}`;link.click()},
openEditor(){if(['.gif','.bmp'].includes(String(this.viewingImage.file_type).toLowerCase()))return this.notify('GIF 与 BMP 可查看和下载，但暂不支持安全编辑导出','error');this.showEditor=true;this.originalCanvas=null;this.resetEditor();this.$nextTick(this.initEditor)},requestCloseEditor(){this.editorDirty?this.showDiscard=true:this.closeEditor()},closeEditor(){this.showDiscard=false;this.showSaveOptions=false;this.showReplaceConfirm=false;this.showNewImage=false;this.showEditor=false;this.originalCanvas=null;this.sourceCanvas=null;this.editorCanvas=null;this.cropRect=null},initEditor(){const canvas=this.$refs.editorCanvas;if(!canvas)return;this.editorCanvas=canvas;this.editorLoading=true;const image=new Image();image.onload=()=>{const src=document.createElement('canvas');src.width=image.naturalWidth;src.height=image.naturalHeight;src.getContext('2d').drawImage(image,0,0);this.originalCanvas=src;this.sourceCanvas=src;this.editorLoading=false;this.renderEditor(false)};image.onerror=()=>{this.editorLoading=false;this.editorError='无法载入图片，无法开始编辑。'};image.src=this.imageUrl(this.viewingImage)},resetEditor(){this.adjustments={brightness:100,contrast:100,saturation:100};this.filterMode='none';this.rotation=0;this.flipH=1;this.flipV=1;this.isCropping=false;this.cropRect=null;this.editorDirty=false;this.editorStatus='';if(this.originalCanvas){const copy=document.createElement('canvas');copy.width=this.originalCanvas.width;copy.height=this.originalCanvas.height;copy.getContext('2d').drawImage(this.originalCanvas,0,0);this.sourceCanvas=copy;this.renderEditor(false)}},filter(){return `${this.filterMode} brightness(${this.adjustments.brightness/100}) contrast(${this.adjustments.contrast/100}) saturate(${this.adjustments.saturation/100})`},renderEditor(markDirty=true){const source=this.sourceCanvas,canvas=this.editorCanvas;if(!source||!canvas)return;const swap=Math.abs(this.rotation)%180===90;canvas.width=swap?source.height:source.width;canvas.height=swap?source.width:source.height;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(this.rotation*Math.PI/180);ctx.scale(this.flipH,this.flipV);ctx.filter=this.filter();ctx.drawImage(source,-source.width/2,-source.height/2);ctx.restore();if(markDirty)this.editorDirty=true},setFilter(value){this.filterMode=value;this.renderEditor()},rotate(value){this.rotation=(this.rotation+value+360)%360;this.cropRect=null;this.renderEditor()},flip(axis){axis==='x'?this.flipH*=-1:this.flipV*=-1;this.cropRect=null;this.renderEditor()},
startCrop(){this.isCropping=true;this.cropRect=null},cancelCrop(){this.isCropping=false;this.cropRect=null},point(event){const c=this.editorCanvas,b=c.getBoundingClientRect();return{x:Math.max(0,Math.min(c.width,(event.clientX-b.left)*c.width/b.width)),y:Math.max(0,Math.min(c.height,(event.clientY-b.top)*c.height/b.height))}},beginCrop(event){if(!this.isCropping||event.target!==this.editorCanvas)return;const point=this.point(event);this.cropAction='new';this.cropOrigin={point};this.cropRect={x:point.x,y:point.y,width:0,height:0};event.currentTarget.setPointerCapture?.(event.pointerId)},beginCropMove(event){if(!this.cropRect)return;this.cropAction='move';this.cropOrigin={point:this.point(event),rect:{...this.cropRect}};event.currentTarget.setPointerCapture?.(event.pointerId)},beginResize(event){if(!this.cropRect)return;this.cropAction=event.currentTarget.dataset.handle;this.cropOrigin={point:this.point(event),rect:{...this.cropRect}};event.currentTarget.setPointerCapture?.(event.pointerId)},moveCrop(event){if(!this.cropAction||!this.cropOrigin)return;const p=this.point(event),c=this.editorCanvas,min=32;if(this.cropAction==='new'){const x=Math.min(p.x,this.cropOrigin.point.x),y=Math.min(p.y,this.cropOrigin.point.y);this.cropRect={x,y,width:Math.abs(p.x-this.cropOrigin.point.x),height:Math.abs(p.y-this.cropOrigin.point.y)};return}const o=this.cropOrigin.rect;if(this.cropAction==='move'){this.cropRect={...o,x:Math.max(0,Math.min(c.width-o.width,o.x+p.x-this.cropOrigin.point.x)),y:Math.max(0,Math.min(c.height-o.height,o.y+p.y-this.cropOrigin.point.y))};return}let l=o.x,r=o.x+o.width,t=o.y,b=o.y+o.height,h=this.cropAction;if(h.includes('w'))l=Math.min(r-min,Math.max(0,p.x));if(h.includes('e'))r=Math.max(l+min,Math.min(c.width,p.x));if(h.includes('n'))t=Math.min(b-min,Math.max(0,p.y));if(h.includes('s'))b=Math.max(t+min,Math.min(c.height,p.y));this.cropRect={x:l,y:t,width:r-l,height:b-t}},endCrop(event){if(this.cropAction)event.currentTarget.releasePointerCapture?.(event.pointerId);this.cropAction=null;this.cropOrigin=null},applyCrop(){const r=this.cropRect,c=this.editorCanvas;if(!r||r.width<32||r.height<32)return this.notify('请选择至少 32 × 32 像素的区域','error');const next=document.createElement('canvas');next.width=Math.round(r.width);next.height=Math.round(r.height);next.getContext('2d').drawImage(c,r.x,r.y,r.width,r.height,0,0,next.width,next.height);this.sourceCanvas=next;this.adjustments={brightness:100,contrast:100,saturation:100};this.filterMode='none';this.rotation=0;this.flipH=1;this.flipV=1;this.cropRect=null;this.isCropping=false;this.renderEditor();this.editorStatus='裁剪已应用'},
blob(){return new Promise((resolve,reject)=>this.editorCanvas.toBlob(blob=>blob?resolve(blob):reject(new Error('无法导出图片')),this.outputFormat,.92))},async editedForm(){const form=new FormData(),blob=await this.blob(),ext=this.outputFormat.split('/')[1].replace('jpeg','jpg');form.append('image',blob,`edited-${Date.now()}.${ext}`);return form},saveAsNew(){this.showSaveOptions=false;this.newImageTitle=`${this.viewingImage.title}（编辑副本）`;this.showNewImage=true},async createDerivative(){this.savingEditor=true;this.editorStatus='正在生成新图片…';try{const form=await this.editedForm();form.append('title',this.newImageTitle.trim()||`${this.viewingImage.title}（编辑副本）`);await axios.post(`/api/entertainment/images/${this.viewingImage.id}/derivatives`,form);this.showNewImage=false;this.editorDirty=false;this.editorStatus='已生成新图片';this.notify('已生成新图片，原图已保留');this.loadImages()}catch(e){this.notify(e.response?.data?.error||'生成失败','error')}finally{this.savingEditor=false}},async replaceImage(){this.savingEditor=true;this.editorStatus='正在替换原图…';try{const form=await this.editedForm();form.append('confirmReplace','true');const result=(await axios.put(`/api/entertainment/images/${this.viewingImage.id}/file`,form)).data;if(result.image)Object.assign(this.viewingImage,{...result.image,cacheKey:Date.now()});this.showReplaceConfirm=false;this.showSaveOptions=false;this.editorDirty=false;this.editorStatus='原图已替换';this.notify('原图已安全替换');this.loadImages()}catch(e){this.notify(e.response?.data?.error||'替换失败','error')}finally{this.savingEditor=false}},
